#[tokio::test]
async fn id_tokens_that_are_refused() {
    let idp = start_idp().await;
    let srv = console(&idp, Store::Memory, |_| {}).await;
    // One good sign-in first: discovery and the JWKS are fetched once.
    srv.sign_in("").await;
    assert_eq!(idp.jwks_hits.load(Ordering::SeqCst), 1);
    let c = |v: Value| Spec { claims: v, ..Default::default() };
    let h = |v: Value| Spec { header: v, ..Default::default() };
    let parts = |spec: Spec| -> Vec<String> {
        set_spec(&idp, spec);
        let t = idp.id_token("n");
        set_spec(&idp, Spec::default());
        t.split('.').map(String::from).collect()
    };
    let es_parts = parts(Spec::default());
    let enc = |v: Value| b64(&serde_json::to_vec(&v).unwrap());
    let cases: Vec<(&str, Spec, &str)> = vec![
        ("wrong iss", c(json!({ "iss": "http://evil.example" })), "iss"),
        ("wrong aud", c(json!({ "aud": "someone-else" })), "aud"),
        ("several aud, no azp", c(json!({ "aud": [CLIENT_ID, "other"] })), "azp"),
        ("expired", c(json!({ "exp": now() - 120 })), "exp"),
        ("issued in the future", c(json!({ "iat": now() + 600 })), "iat"),
        ("wrong nonce", c(json!({ "nonce": "another-login" })), "nonce"),
        ("tampered payload", Spec { tamper: true, ..Default::default() }, "signature"),
        (
            "alg none",
            Spec { raw: Some(format!("{}.{}.", enc(json!({ "alg": "none" })), es_parts[1])), ..Default::default() },
            "alg none",
        ),
        (
            "HS256",
            Spec {
                raw: Some(format!("{}.{}.{}", enc(json!({ "alg": "HS256" })), es_parts[1], es_parts[2])),
                ..Default::default()
            },
            "HS256",
        ),
        ("crit header", h(json!({ "crit": ["exp"] })), "crit"),
        ("jwk alg mismatch", h(json!({ "kid": "es1", "alg": "ES384" })), "alg"),
    ];
    for (what, spec, why) in cases {
        set_spec(&idp, spec);
        let desc = srv.refused("token_rejected").await;
        assert!(desc.contains(why), "{what}: {desc}");
    }
    assert_eq!(idp.jwks_hits.load(Ordering::SeqCst), 1, "known keys are served from the cache");

    // An unknown kid refetches the JWKS once; a second one within the minute does not.
    set_spec(&idp, h(json!({ "kid": "rotated-away" })));
    let desc = srv.refused("token_rejected").await;
    assert!(desc.contains("rotated-away"), "{desc}");
    assert_eq!(idp.jwks_hits.load(Ordering::SeqCst), 2);
    set_spec(&idp, h(json!({ "kid": "another-unknown" })));
    srv.refused("token_rejected").await;
    assert_eq!(idp.jwks_hits.load(Ordering::SeqCst), 2, "at most one refetch a minute");

    // The good path still works after all that.
    set_spec(&idp, Spec::default());
    srv.sign_in("").await;
}

#[tokio::test]
async fn sign_up_rules() {
    let idp = start_idp().await;
    // Sign-up closed: only invited people get in.
    let srv = console(&idp, Store::Memory, |c| c.console.allow_signup = false).await;
    set_user(&idp, "stranger", Some("stranger@example.com"), true);
    assert!(srv.refused("signup_closed").await.contains("invitation"));
    // The bootstrap admin invites by email and shares a code link.
    let (st, admin) = srv.call(Method::POST, "/v1/console/auth/token", Some(BOOTSTRAP), None).await;
    assert_eq!(st, 200, "{admin}");
    let token = admin["token"].as_str().unwrap();
    let org = admin["org"]["id"].as_str().unwrap();
    let inv_path = format!("/v1/console/orgs/{org}/invitations");
    let invite =
        |email: &str| srv.call(Method::POST, &inv_path, Some(token), Some(json!({ "email": email, "role": "viewer" })));
    let (st, _) = invite("stranger@example.com").await;
    assert_eq!(st, 200);
    let (stranger, _) = srv.sign_in("").await;
    let (_, me) = srv.call(Method::GET, "/v1/console/me", Some(&stranger), None).await;
    assert_eq!((me["orgs"][0]["id"].as_str(), me["orgs"][0]["role"].as_str()), (Some(org), Some("viewer")));
    // An invitation code works whatever the email (here: unverified).
    let (_, inv) = invite("someone@else.example").await;
    let code = inv["link"].as_str().unwrap().split("code=").nth(1).unwrap().to_string();
    set_user(&idp, "linked", Some("linked@elsewhere.example"), false);
    srv.refused("signup_closed").await;
    let (linked, _) = srv.sign_in(&format!("&invite={code}")).await;
    let (_, me) = srv.call(Method::GET, "/v1/console/me", Some(&linked), None).await;
    assert_eq!(me["orgs"][0]["id"].as_str(), Some(org));
    // An existing user signs in although sign-up is closed.
    srv.sign_in("").await;

    // A domain allowlist checks the verified email only.
    let srv = console(&idp, Store::Memory, |c| c.console.allowed_email_domains = vec!["example.com".into()]).await;
    set_user(&idp, "unverified", Some("unverified@example.com"), false);
    assert!(srv.refused("domain_not_allowed").await.contains("verified"));
    set_user(&idp, "outsider", Some("outsider@other.example"), true);
    srv.refused("domain_not_allowed").await;
    set_user(&idp, "insider", Some("insider@EXAMPLE.com"), true);
    let (insider, _) = srv.sign_in("").await;
    let (_, me) = srv.call(Method::GET, "/v1/console/me", Some(&insider), None).await;
    assert_eq!(me["orgs"].as_array().unwrap().len(), 1);

    // Without create_org_on_signup a new user has no organization.
    let srv = console(&idp, Store::Memory, |c| c.console.create_org_on_signup = false).await;
    set_user(&idp, "solo", Some("solo@example.com"), true);
    let (solo, _) = srv.sign_in("").await;
    let (_, me) = srv.call(Method::GET, "/v1/console/me", Some(&solo), None).await;
    assert_eq!(me["orgs"], json!([]));
}

#[tokio::test]
async fn starts_are_limited_and_an_unreachable_idp_is_explained() {
    let idp = start_idp().await;
    let srv = console(&idp, Store::Memory, |c| {
        let mut down = c.console.oidc[0].clone();
        down.id = "down".into();
        down.issuer = "http://127.0.0.1:9".into();
        down.client_secret_env = None;
        c.console.oidc.push(down);
    })
    .await;
    let hash = binding().1;
    let r = srv.http.get(format!("{}/v1/console/auth/oidc/down/start?binding={hash}", srv.base)).send().await.unwrap();
    assert_eq!(r.status(), 503);
    let v: Value = r.json().await.unwrap();
    let msg = v["error"]["message"].as_str().unwrap();
    assert!(msg.contains("'down'") && msg.contains("cannot be reached"), "{msg}");
    // 20 starts a minute per server, that one included.
    for i in 1..20 {
        let (st, _, v) = srv.start(&format!("binding={hash}")).await;
        assert_eq!(st, 302, "start {i}: {v}");
    }
    let r = srv.http.get(format!("{}/v1/console/auth/oidc/mock/start?binding={hash}", srv.base)).send().await.unwrap();
    assert_eq!(r.status(), 429);
    assert_eq!(r.headers()[header::RETRY_AFTER], "60");
}

#[tokio::test]
async fn startup_checks_the_providers() {
    let base = || {
        let mut cfg = Config::in_memory();
        cfg.console.oidc = vec![OidcProviderConfig {
            id: "idp".into(),
            name: "IdP".into(),
            issuer: "https://idp.example.com".into(),
            client_id: "cid".into(),
            client_secret_env: Some("ONTO_OIDC_IDP_SECRET_FOR_TESTS".into()),
            scopes: vec!["openid".into()],
            audiences: vec![],
        }];
        cfg.console
    };
    let with_secret = || {
        let mut o = ControlOptions::default();
        o.oidc_secrets.insert("idp".into(), "s".into());
        o
    };
    assert!(Control::memory(base(), with_secret()).is_ok());
    let err = Control::memory(base(), ControlOptions::default()).unwrap_err().to_string();
    assert!(err.contains("ONTO_OIDC_IDP_SECRET_FOR_TESTS"), "{err}");
    let mut public = base();
    public.oidc[0].client_secret_env = None;
    assert!(Control::memory(public, ControlOptions::default()).is_ok(), "a public client needs no secret");
    let mut bad = base();
    bad.oidc[0].id = "Bad_Id".into();
    assert!(Control::memory(bad, with_secret()).is_err());
    let mut bad = base();
    bad.oidc[0].issuer = "http://idp.example.com".into();
    assert!(Control::memory(bad, with_secret()).unwrap_err().to_string().contains("https"));
    let mut twice = base();
    twice.oidc.push(twice.oidc[0].clone());
    assert!(Control::memory(twice, with_secret()).unwrap_err().to_string().contains("twice"));
}
